(function(root){
'use strict';
const identity=Object.freeze({chainId:56,agentId:370316,registry:'0x8004a169fb4a3325136eb29fa0ceb6d2e539a432',owner:'0xdcf64cddc4a2b06f756f21a125ca393792dfa709',registrationURI:'https://fual-treasury-agent.phamphuanloc.chatgpt.site/registration.json',executionChainId:97});
const journalKey='fual-treasury-evidence-v1',schema='fual-owner-approved-execution-v1';
function normal(x){if(typeof x==='bigint')return {bigint:x.toString()};if(Array.isArray(x))return x.map(normal);if(x&&typeof x==='object')return Object.fromEntries(Object.keys(x).sort().filter(k=>x[k]!==undefined).map(k=>[k,normal(x[k])]));if(typeof x==='number'&&!Number.isFinite(x))throw Error('Dữ liệu bằng chứng không hợp lệ.');return x;}
async function digest(x){const b=new TextEncoder().encode(JSON.stringify(normal(x)));return '0x'+Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');}
async function readIdentityRPC(items){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch('https://bsc-dataseed.bnbchain.org',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(items.map(([method,params],id)=>({jsonrpc:'2.0',id,method,params}))),signal:controller.signal});if(!response.ok)throw Error('Chưa đọc được danh tính agent trên mainnet.');const body=await response.json(),values=new Map();if(!Array.isArray(body)||body.length!==items.length)throw Error('Thiếu dữ liệu danh tính.');for(const x of body){if(!Number.isInteger(x.id)||x.id<0||x.id>=items.length||values.has(x.id)||x.error||!Object.hasOwn(x,'result'))throw Error('Dữ liệu danh tính không hợp lệ.');values.set(x.id,x.result);}return items.map((_,i)=>values.get(i));}finally{clearTimeout(timer);}}
function decodeURI(hex){if(typeof hex!=='string'||!/^0x(?:[0-9a-f]{2})+$/i.test(hex)||hex.length>8194)throw Error('URI agent không hợp lệ.');const b=Uint8Array.from(hex.slice(2).match(/../g),x=>parseInt(x,16));const word=offset=>{if(offset+32>b.length)throw Error('URI agent thiếu dữ liệu.');return BigInt('0x'+Array.from(b.slice(offset,offset+32),x=>x.toString(16).padStart(2,'0')).join(''));};if(word(0)!==32n)throw Error('URI agent sai định dạng.');const n=Number(word(32));if(n<1||n>2048||64+n>b.length)throw Error('URI agent sai độ dài.');return new TextDecoder('utf-8',{fatal:true}).decode(b.slice(64,64+n));}
async function checkIdentity(read=readIdentityRPC){const [chain,block]=await read([['eth_chainId',[]],['eth_blockNumber',[]]]);if(BigInt(chain)!==56n)throw Error('Sai mạng xác minh danh tính agent.');const id=identity.agentId.toString(16).padStart(64,'0');const [owner,uri,head]=await read([['eth_call',[{to:identity.registry,data:'0x6352211e'+id},block]],['eth_call',[{to:identity.registry,data:'0xc87b56dd'+id},block]],['eth_getBlockByNumber',[block,false]]]);if(typeof owner!=='string'||!/^0x0{24}[a-f0-9]{40}$/i.test(owner)||'0x'+owner.slice(-40).toLowerCase()!==identity.owner)throw Error('Chủ sở hữu agent đã thay đổi; dừng mở ví.');if(decodeURI(uri)!==identity.registrationURI)throw Error('URI agent đã thay đổi; dừng mở ví.');const stamp=Number(BigInt(head?.timestamp)),now=Math.floor(Date.now()/1000);if(!head||!/^0x[a-f0-9]{64}$/i.test(head.hash)||!Number.isSafeInteger(stamp)||stamp>now||now-stamp>60)throw Error('Dữ liệu danh tính đã cũ; dừng mở ví.');return {...identity,registryBlock:block,registryBlockHash:head.hash,checkedAt:new Date(now*1000).toISOString(),registryObservedAt:new Date(stamp*1000).toISOString()};}
async function seal(plan,binding,policy){return {schema,binding,policy:normal(policy),planHash:await digest({schema,binding,policy,plan}),attribution:'owner-approved controller evidence; not a registry attestation or organizer qualification'};}
async function verifySeal(plan,proof){if(!proof||proof.schema!==schema||proof.binding?.agentId!==identity.agentId||proof.binding?.owner!==identity.owner||proof.binding?.registrationURI!==identity.registrationURI||proof.planHash!==await digest({schema,binding:proof.binding,policy:proof.policy,plan}))throw Error('Hồ sơ kế hoạch đã thay đổi; dừng xử lý.');}
async function readJournal(storage){const raw=storage.getItem(journalKey);if(!raw)return {schema,entries:[]};let j;try{j=JSON.parse(raw);}catch{throw Error('Không đọc được nhật ký; chưa mở ví.');}if(j.schema!==schema||!Array.isArray(j.entries)||j.entries.length>1000)throw Error('Nhật ký sai định dạng; chưa mở ví.');let previous=null;for(const e of j.entries){const {hash,...body}=e;if(body.previous!==previous||hash!==await digest(body))throw Error('Nhật ký đã thay đổi; xuất hồ sơ và kiểm tra trước.');previous=hash;}return j;}
async function append(storage,key,event,data){const j=await readJournal(storage),existing=j.entries.find(e=>e.key===key);if(existing){if(existing.event!==event||JSON.stringify(existing.data)!==JSON.stringify(normal(data)))throw Error('Nhật ký trùng mã nhưng khác nội dung.');return existing;}if(j.entries.length>=1000)throw Error('Nhật ký đầy; xuất hồ sơ trước khi tiếp tục.');const body=normal({key,event,data,at:new Date().toISOString(),previous:j.entries.at(-1)?.hash??null}),entry={...body,hash:await digest(body)};j.entries.push(entry);const serialized=JSON.stringify(j);if(new TextEncoder().encode(serialized).length>2000000)throw Error('Nhật ký quá lớn; xuất hồ sơ trước khi tiếp tục.');storage.setItem(journalKey,serialized);return entry;}
const api={identity,journalKey,schema,digest,decodeURI,checkIdentity,seal,verifySeal,readJournal,append};if(typeof module==='object'&&module.exports)module.exports=api;else root.TreasuryEvidence=api;
})(typeof window==='object'?window:globalThis);
